def L(*pairs):
    return [{"label": a, "href": b} for a, b in pairs]


def row(year, date, title, corr, place, lang, region, period, shelf, folio, cls, status, why, imp, solv, diff,
        verify, links, src, prior=CHK, seen="catalogue", archive=None, decode=None):
    r = dict(year=year, date=date, title=title, correspondents=corr, place=place, language=lang, region=region,
             period=period, shelfmark=shelf, folio_note=folio, cls=cls, status=status, why=why, importance=imp,
             solvability=solv, difficulty=diff, score_note=SN.format(a=archive or src), verify=verify, links=links,
             seen=seen, source=src + " sweep", prior_art=prior)
    if decode:
        r["decode_ids"] = decode
    return r


